{"path": "/home/daytona/test_daytona.ts", "content": "import { Daytona } from '@daytona/sdk';

async function main() {
    const daytona = new Daytona();
    const sandbox = await daytona.create();
    console.log(`Sandbox created: ${sandbox.id}`);
    console.log(`Sandbox state: ${sandbox.state}`);
    console.log(`Sandbox target: ${sandbox.target}`);
    console.log(`Sandbox toolbox_proxy_url: ${sandbox.toolboxProxyUrl}`);

    // Wait for sandbox to be ready
    await sandbox.waitForSandboxStart();
    console.log("Sandbox is ready");

    // Run code inside the sandbox
    const response = await sandbox.process.exec("echo 'Hello from inside the sandbox!'");
    console.log(`Exit code: ${response.exitCode}`);
    console.log(`Output: ${response.result}`);

    // Clean up
    await sandbox.delete();
    console.log("Sandbox deleted");
}

main().catch(console.error);
